package info.deltaindices.volumecamera;
import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.result.ActivityResultLauncher;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.AppCompatActivity;import java.util.*;

public final class CaptureActivity extends AppCompatActivity {
 static final String ACTION_TOGGLE="info.deltaindices.volumecamera.TOGGLE";private Button toggle;private TextView count;private boolean autoToggle,startAfterPermission;
 private final ActivityResultLauncher<String[]> permissions=registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(),result->{if(startAfterPermission){startAfterPermission=false;if(Boolean.TRUE.equals(result.get(Manifest.permission.CAMERA))&&Boolean.TRUE.equals(result.get(Manifest.permission.RECORD_AUDIO)))startCapture();else Toast.makeText(this,"Camera and microphone permissions are required",Toast.LENGTH_LONG).show();}});
 private final BroadcastReceiver updates=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){render(i.getBooleanExtra("active",false),i.getIntExtra("count",0));}};
 @Override protected void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=27){setShowWhenLocked(true);setTurnScreenOn(true);}else getWindow().addFlags(WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);setContentView(build());autoToggle=ACTION_TOGGLE.equals(getIntent().getAction());refresh();}
 @Override protected void onPostResume(){super.onPostResume();if(autoToggle){autoToggle=false;toggle();}}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);if(ACTION_TOGGLE.equals(i.getAction())){autoToggle=true;if(hasWindowFocus()){autoToggle=false;toggle();}}}
 @Override protected void onStart(){super.onStart();ContextCompatHelper.register(this,updates,new IntentFilter(CaptureService.ACTION_COUNT));refresh();}
 @Override protected void onStop(){unregisterReceiver(updates);super.onStop();}
 private View build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setGravity(Gravity.CENTER);root.setBackgroundColor(Color.BLACK);count=new TextView(this);count.setTextSize(56);count.setTextColor(Color.WHITE);count.setGravity(Gravity.CENTER);root.addView(count,new LinearLayout.LayoutParams(-1,0,1));toggle=new Button(this);toggle.setTextSize(28);toggle.setOnClickListener(v->toggle());root.addView(toggle,new LinearLayout.LayoutParams(-1,180));return root;}
 private void toggle(){boolean active=Settings.prefs(this).getBoolean(Settings.CAPTURE_ACTIVE,false);if(active){startService(new Intent(this,CaptureService.class).setAction(CaptureService.ACTION_STOP));render(false,Settings.prefs(this).getInt(Settings.SESSION_COUNT,0));return;}if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){startAfterPermission=true;permissions.launch(new String[]{Manifest.permission.CAMERA,Manifest.permission.RECORD_AUDIO});return;}startCapture();}
 private void startCapture(){startForegroundService(new Intent(this,CaptureService.class).setAction(CaptureService.ACTION_START));render(true,0);}
 private void refresh(){boolean active=Settings.prefs(this).getBoolean(Settings.CAPTURE_ACTIVE,false);render(active,Settings.prefs(this).getInt(Settings.SESSION_COUNT,0));String error=Settings.prefs(this).getString(Settings.CAPTURE_ERROR,null);if(!active&&error!=null){Settings.prefs(this).edit().remove(Settings.CAPTURE_ERROR).apply();Toast.makeText(this,error,Toast.LENGTH_LONG).show();}}
 private void render(boolean active,int value){count.setText(String.valueOf(value));toggle.setText(active?"STOP":"START");toggle.setTextColor(Color.WHITE);toggle.setBackgroundColor(active?Color.rgb(190,35,35):Color.rgb(20,150,70));}
}
